@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + roomNumber : int
  + maxCapacity : int
}

class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Trainer {
  + diploma : string
}

class Member {
}

class Prospect {
}

class Intern {
}

class Session {
  + date : date
  + startHour : time
}

class IndividualSession {
}

class GroupSession {
  + sessionType : string
}

Center "1" *-- "1..*" Room
Room "1" *-- "0..*" Session
Trainer --|> Person
Member --|> Person
Prospect --|> Person
Intern --|> Trainer

Person "0..*" -- "0..*" Session : participates
Trainer "1" -- "0..*" GroupSession : supervises
GroupSession --|> Session
IndividualSession --|> Session

@enduml

